    mix(u_color3, vec3(1.0), 0.2),
    mix(u_color4, u_color3, 0.55 + 0.15 * sin(u_time + uv.y * 8.0)),
    clamp(0.25 + uv.y * 0.65 + sin(uv.x * 7.0 + u_time * 0.6) * 0.08, 0.0, 1.0)
